//! 🎬️ Owned vector plans and indexed painted caches publish as one completed scene.
use super::{PaintedPathPrepareJob,PaintedPathRegions,PaintedRegionLimits,PaintedPreparationRetirement,PaintedRegionsCloseJob};
use crate::schema::{scene_preparation::{DocumentScenePlan,DocumentSceneContent},scene_retirement::ScenePlanCloseJob};
use semio_framework_2d::retirement::{WorkRetirementCounter,WorkRetirementProgress};
type Point=[f64;2];type Bounds=[f64;4];
#[derive(Clone,Debug)]
pub struct PaintedSceneLimits{pub max_nodes:usize,pub max_segments:usize,pub max_points:usize,pub max_contours:usize,pub max_work:u64}
#[derive(Clone,Copy,Debug,Default,PartialEq,Eq)]
pub struct PreparedSceneCounts{pub nodes:usize,pub segments:usize,pub points:usize,pub contours:usize}
#[derive(Debug)]
pub enum PreparedPaint{Empty,Path(PaintedPathRegions),Image([Point;4]),TextFallback([Point;4])}
#[derive(Debug)]
pub struct PreparedGeometry{pub geometry_bounds:Option<Bounds>,pub bounds:Option<Bounds>,pub paint:PreparedPaint}
#[derive(Debug)]
pub struct PreparedScene{pub plan:DocumentScenePlan,pub geometry:Vec<PreparedGeometry>,pub flatness:f64,pub counts:PreparedSceneCounts}
#[derive(Clone,Copy,Debug)]
pub struct ScenePaintProgress{pub phase:&'static str,pub work:u64,pub nodes:usize,pub segments:usize,pub points:usize,pub contours:usize,pub done:bool}
fn valid(v:f64)->bool{v.is_finite()&&v.abs()<=1e9}
fn union(a:Option<Bounds>,b:Bounds)->Bounds{a.map_or(b,|a|[a[0].min(b[0]),a[1].min(b[1]),a[2].max(b[2]),a[3].max(b[3])])}
fn rectangle(x:f64,y:f64,w:f64,h:f64,m:[f64;6])->Result<PreparedGeometry,String>{let mut corners=[[x,y],[x+w,y],[x+w,y+h],[x,y+h]];let mut bounds=None;for p in &mut corners{*p=[m[0]*p[0]+m[2]*p[1]+m[4],m[1]*p[0]+m[3]*p[1]+m[5]];if !p.iter().copied().all(valid){return Err("Painted scene coordinate limit exceeded".into());}bounds=Some(union(bounds,[p[0],p[1],p[0],p[1]]));}Ok(PreparedGeometry{geometry_bounds:bounds,bounds,paint:PreparedPaint::Image(corners)})}
/// 🧹️ Adopts actual cache entries and the genuine owned vector-plan close frontier.
pub struct PreparedSceneCloseJob{geometry:Vec<PreparedGeometry>,extra:Option<PreparedGeometry>,plan:Option<ScenePlanCloseJob>,regions:Option<PaintedRegionsCloseJob>,phase:u8,counter:WorkRetirementCounter}
impl PreparedSceneCloseJob{
 pub fn new(scene:PreparedScene)->Self{Self::partial(scene.plan,scene.geometry,None)}
 fn partial(plan:DocumentScenePlan,geometry:Vec<PreparedGeometry>,extra:Option<PreparedGeometry>)->Self{Self{geometry,extra,plan:Some(ScenePlanCloseJob::new(plan)),regions:None,phase:0,counter:Default::default()}}
 fn step(&mut self)->bool{if let Some(c)=&mut self.regions{if !c.terminal_is_empty(){c.advance(1).expect("positive scene region close");return false;}self.regions=None;return false;}if self.phase==0{if let Some(g)=self.extra.take().or_else(||self.geometry.pop()){if let PreparedPaint::Path(regions)=g.paint{self.regions=Some(PaintedRegionsCloseJob::new(regions));}return false;}self.geometry=Vec::new();self.phase=1;return false;}if let Some(c)=&mut self.plan{if !c.terminal_is_empty(){c.advance(1).expect("positive owned scene close");return false;}self.plan=None;return false;}self.phase=2;true}
 pub fn terminal_is_empty(&self)->bool{self.phase==2&&self.plan.is_none()&&self.regions.is_none()&&self.geometry.is_empty()&&self.extra.is_none()}
 pub fn advance(&mut self,grant:usize)->Result<WorkRetirementProgress,&'static str>{let mut c=self.counter;let result=c.advance(grant,||self.step());self.counter=c;result}
}
/// 🧱️ Constructor adoption preserves refused owned input for work-granted retirement.
pub struct ScenePaintJob{
 plan:Option<DocumentScenePlan>,limits:PaintedSceneLimits,flatness:f64,geometry:Vec<PreparedGeometry>,counts:PreparedSceneCounts,phase:&'static str,work:u64,validated:bool,index:usize,segment:usize,pen:Point,origin:Point,bounds:Option<Bounds>,
 text_at:usize,columns:usize,maximum_columns:usize,lines:usize,cr:bool,path:Option<PaintedPathPrepareJob>,path_retirement:Option<PaintedPreparationRetirement>,pending:Option<PreparedGeometry>,output:Option<PreparedScene>,cancelled:bool,failure:Option<String>,
}
impl ScenePaintJob{
 pub fn new(plan:DocumentScenePlan,flatness:f64,limits:PaintedSceneLimits)->Self{Self{plan:Some(plan),limits,flatness,geometry:Vec::new(),counts:Default::default(),phase:"nodes",work:0,validated:false,index:0,segment:0,pen:[0.0;2],origin:[0.0;2],bounds:None,text_at:0,columns:0,maximum_columns:0,lines:1,cr:false,path:None,path_retirement:None,pending:None,output:None,cancelled:false,failure:None}}
 fn validate(&mut self)->Result<(),String>{let l=&self.limits;if !self.flatness.is_finite()||!(1e-6..=16.0).contains(&self.flatness)||l.max_nodes==0||l.max_nodes>1024||l.max_segments==0||l.max_segments>65536||l.max_points==0||l.max_points>262144||l.max_contours==0||l.max_contours>65536||l.max_work==0||l.max_work>1000000000{return Err("Invalid painted scene contract".into());}if self.plan.as_ref().unwrap().nodes.len()>l.max_nodes{return Err("Painted scene node limit exceeded".into());}self.validated=true;Ok(())}
 fn admit(&mut self,g:PreparedGeometry)->Result<(),String>{let(points,contours)=match &g.paint{PreparedPaint::Empty=>(0,0),PreparedPaint::Path(r)=>(r.points,r.contours),_=>(4,1)};if self.counts.points+points>self.limits.max_points||self.counts.contours+contours>self.limits.max_contours{self.pending=Some(g);return Err("Painted scene cache count limit exceeded".into());}self.geometry.push(g);self.counts.points+=points;self.counts.contours+=contours;self.counts.nodes+=1;self.index+=1;self.phase="nodes";Ok(())}
 fn step(&mut self)->Result<(),String>{if !self.validated{return self.validate();}let node=self.plan.as_ref().unwrap().nodes.get(self.index);match self.phase{
  "nodes"=>{let Some(node)=node else{self.output=Some(PreparedScene{plan:self.plan.take().unwrap(),geometry:std::mem::take(&mut self.geometry),flatness:self.flatness,counts:self.counts});self.phase="complete";return Ok(());};if !node.transform.into_iter().all(valid){return Err("Painted scene transform limit exceeded".into());}if matches!(node.content,DocumentSceneContent::Boolean{..}|DocumentSceneContent::Trace{..}){return Err("Unresolved algorithm in painted scene".into());}if let DocumentSceneContent::Path{segments,..}=&node.content{if self.counts.segments+segments.len()>self.limits.max_segments{return Err("Painted scene segment limit exceeded".into());}self.counts.segments+=segments.len();}self.bounds=None;self.segment=0;self.pen=[0.0;2];self.origin=self.pen;if !node.visible||matches!(node.content,DocumentSceneContent::Group{..}){self.admit(PreparedGeometry{geometry_bounds:None,bounds:None,paint:PreparedPaint::Empty})?;}else{match &node.content{DocumentSceneContent::Path{stroke,..}=>{if stroke.as_ref().and_then(|s|s.dash.as_ref()).is_some_and(|d|d.len()>1024){return Err("Painted scene stroke limit exceeded".into());}self.phase="bounds";},DocumentSceneContent::Image{width,height,..}=>{let g=rectangle(0.0,0.0,*width,*height,node.transform)?;self.admit(g)?;},DocumentSceneContent::Text{..}=>{self.text_at=0;self.columns=0;self.maximum_columns=0;self.lines=1;self.cr=false;self.phase="text";},_=>unreachable!()}}},
  "bounds"=>{let node=node.unwrap();let DocumentSceneContent::Path{segments,..}=&node.content else{unreachable!()};if let Some(s)=segments.get(self.segment){if !matches!(s,crate::PathSegment::Close)||self.bounds.is_some(){let b=crate::schema::geometry::segment_bounds(s,self.pen,self.origin,node.transform);let world=[b[0],b[1],b[0]+b[2],b[1]+b[3]];if !world.into_iter().all(valid){return Err("Painted scene bounds limit exceeded".into());}self.bounds=Some(union(self.bounds,world));}match s{crate::PathSegment::Move{to}=>{self.pen=*to;self.origin=*to},crate::PathSegment::Close=>self.pen=self.origin,crate::PathSegment::Line{to}|crate::PathSegment::Quad{to,..}|crate::PathSegment::Cubic{to,..}|crate::PathSegment::Arc{to,..}=>self.pen=*to}self.segment+=1;}else{self.path=Some(PaintedPathPrepareJob::from_prepared(node,self.flatness,PaintedRegionLimits{max_segments:65536,max_points:262144,max_contours:65536,max_work:self.limits.max_work})?);self.phase="path";}},
  "text"=>{let node=node.unwrap();let DocumentSceneContent::Text{content,x,y,size,..}=&node.content else{unreachable!()};if let Some(ch)=content[self.text_at..].chars().next(){self.text_at+=ch.len_utf8();if ch=='\r'||ch=='\n'{self.maximum_columns=self.maximum_columns.max(self.columns);self.columns=0;if ch=='\r'||!self.cr{self.lines+=1;}self.cr=ch=='\r';}else{self.columns+=1;self.cr=false;}}else{let w=self.maximum_columns.max(self.columns)as f64*size*0.6;let h=self.lines as f64*size*1.2;let mut g=rectangle(*x,*y,w,h,node.transform)?;let PreparedPaint::Image(corners)=g.paint else{unreachable!()};g.paint=PreparedPaint::TextFallback(corners);self.admit(g)?;}},
  "path"=>{let node=node.unwrap();let DocumentSceneContent::Path{segments,..}=&node.content else{unreachable!()};if self.path.as_mut().unwrap().advance_work(1,|index|segments.get(index).cloned())?{let(c,output)=self.path.take().unwrap().into_retirement();self.path_retirement=Some(c);let regions=output.unwrap();self.pending=Some(PreparedGeometry{geometry_bounds:self.bounds,bounds:regions.bounds,paint:PreparedPaint::Path(regions)});self.phase="pathCleanup";}},
  "pathCleanup"=>{if let Some(c)=&mut self.path_retirement{if !c.terminal_is_empty(){c.advance(1).map_err(str::to_string)?;}else{self.path_retirement=None;}}else{let g=self.pending.take().unwrap();self.admit(g)?;}},"complete"=>{},_=>unreachable!(),}Ok(())}
 pub fn advance(&mut self,grant:usize)->Result<ScenePaintProgress,String>{if grant==0||grant as u128>9007199254740991{return Err("Invalid painted scene work grant".into());}if self.cancelled{return Err("Painted scene cancelled".into());}if let Some(error)=&self.failure{return Err(error.clone());}for _ in 0..grant{if self.phase=="complete"{break;}let step=if self.validated&&self.work>=self.limits.max_work{Err("Painted scene work limit exceeded".into())}else{self.step()};if let Err(error)=step{self.failure=Some(error.clone());return Err(error);}self.work+=1;}Ok(ScenePaintProgress{phase:self.phase,work:self.work,nodes:self.counts.nodes,segments:self.counts.segments,points:self.counts.points,contours:self.counts.contours,done:self.phase=="complete"})}
 pub fn result(&self)->Result<&PreparedScene,String>{if self.cancelled{return Err("Painted scene cancelled".into());}if let Some(error)=&self.failure{return Err(error.clone());}if self.phase!="complete"{return Err("Painted scene incomplete".into());}Ok(self.output.as_ref().unwrap())}
 pub fn cancel(&mut self){self.cancelled=true;}
 pub fn into_retirement(mut self)->(ScenePaintRetirement,Option<PreparedScene>){let success=self.result().is_ok();let output=if success{self.output.take()}else{None};let discard=if let Some(scene)=self.output.take(){Some(PreparedSceneCloseJob::new(scene))}else{self.plan.take().map(|plan|PreparedSceneCloseJob::partial(plan,std::mem::take(&mut self.geometry),self.pending.take()))};self.cancelled=true;if let Some(mut path)=self.path.take(){path.cancel();self.path_retirement=Some(path.into_retirement().0);}(ScenePaintRetirement{job:Some(self),discard,counter:Default::default()},output)}
}
/// 🧾️ Keeps source plan/cache owners until actual active path retirement is terminal.
pub struct ScenePaintRetirement{job:Option<ScenePaintJob>,discard:Option<PreparedSceneCloseJob>,counter:WorkRetirementCounter}
impl ScenePaintRetirement{
 pub fn terminal_is_empty(&self)->bool{self.job.is_none()&&self.discard.is_none()}
 pub fn advance(&mut self,grant:usize)->Result<WorkRetirementProgress,&'static str>{let mut c=self.counter;let result=c.advance(grant,||{if let Some(job)=&mut self.job{if let Some(path)=&mut job.path_retirement{if !path.terminal_is_empty(){path.advance(1).expect("positive scene path retirement");return false;}job.path_retirement=None;return false;}self.job=None;return false;}if let Some(close)=&mut self.discard{if !close.terminal_is_empty(){close.advance(1).expect("positive prepared scene retirement");return false;}self.discard=None;return false;}true});self.counter=c;result}
}
